class FfiConverterTypeFsyncEngine: FfiConverter<FsyncEngine, IntPtr> {
    public static FfiConverterTypeFsyncEngine INSTANCE = new FfiConverterTypeFsyncEngine();


    public override IntPtr Lower(FsyncEngine value) {
        return value.CallWithPointer(thisPtr => thisPtr);
    }

    public override FsyncEngine Lift(IntPtr value) {
        return new FsyncEngine(value);
    }

    public override FsyncEngine Read(BigEndianStream stream) {
        return Lift(new IntPtr(stream.ReadLong()));
    }

    public override int AllocationSize(FsyncEngine value) {
        return 8;
    }

    public override void Write(FsyncEngine value, BigEndianStream stream) {
        stream.WriteLong(Lower(value).ToInt64());
    }
}



