/// <param name="data_dir">
/// Holds `history.db` and `blobs/`.
/// </param>
/// <param name="relay_url">
/// Our relay (none: LAN only). Merged with `relay_urls`.
/// </param>
/// <param name="device_secret">
/// 32 bytes, from Keychain / DPAPI.
/// </param>
/// <param name="history_key">
/// 32 bytes, from Keychain / DPAPI.
/// </param>
/// <param name="force_relay">
/// Test flag: relay only, no direct paths.
/// </param>
/// <param name="allow_insecure_http">
/// Dev backends on plain http.
/// </param>
/// <param name="relay_urls">
/// More relays, e.g. one per region: iroh picks the home relay by latency. Merged with
/// `relay_url` and deduplicated; https only unless `allow_insecure_http`. Added after v2, kept last (uniffi records are positional),
/// defaults to `[]`.
/// </param>
public record EngineConfig (
    /// <summary>
    /// Holds `history.db` and `blobs/`.
    /// </summary>
    string @dataDir, 
    string @apiBase, 
    /// <summary>
    /// Our relay (none: LAN only). Merged with `relay_urls`.
    /// </summary>
    string? @relayUrl, 
    string @deviceName, 
    Platform @platform, 
    /// <summary>
    /// 32 bytes, from Keychain / DPAPI.
    /// </summary>
    byte[] @deviceSecret, 
    /// <summary>
    /// 32 bytes, from Keychain / DPAPI.
    /// </summary>
    byte[] @historyKey, 
    /// <summary>
    /// Test flag: relay only, no direct paths.
    /// </summary>
    bool @forceRelay, 
    /// <summary>
    /// Dev backends on plain http.
    /// </summary>
    bool @allowInsecureHttp, 
    /// <summary>
    /// More relays, e.g. one per region: iroh picks the home relay by latency. Merged with
    /// `relay_url` and deduplicated; https only unless `allow_insecure_http`. Added after v2, kept last (uniffi records are positional),
    /// defaults to `[]`.
    /// </summary>
    string[] @relayUrls = null
) {
}

class FfiConverterTypeEngineConfig: FfiConverterRustBuffer<EngineConfig> {
