public record AccountEvent {
    
    public record ListAdvanced (
        ulong @seq
    ) : AccountEvent {}
    
    public record SelfRemoved: AccountEvent {}
    
    
    public record TrustReset (
        string @resetId,
        uint @devices,
        string[] @deviceNames
    ) : AccountEvent {}
    
    public record HistoryReset (
        string @backup
    ) : AccountEvent {}
    
    public record SessionExpired: AccountEvent {}
    
    

    
}

class FfiConverterTypeAccountEvent : FfiConverterRustBuffer<AccountEvent>{
    public static FfiConverterRustBuffer<AccountEvent> INSTANCE = new FfiConverterTypeAccountEvent();

    public override AccountEvent Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new AccountEvent.ListAdvanced(
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 2:
                return new AccountEvent.SelfRemoved(
                );
            case 3:
                return new AccountEvent.TrustReset(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream),
                    FfiConverterSequenceString.INSTANCE.Read(stream)
                );
            case 4:
                return new AccountEvent.HistoryReset(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 5:
                return new AccountEvent.SessionExpired(
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeAccountEvent.Read()", value));
        }
    }

    public override int AllocationSize(AccountEvent value) {
        switch (value) {
            case AccountEvent.ListAdvanced variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@seq);
            case AccountEvent.SelfRemoved variant_value:
                return 4;
            case AccountEvent.TrustReset variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@resetId)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.@devices)
                    + FfiConverterSequenceString.INSTANCE.AllocationSize(variant_value.@deviceNames);
            case AccountEvent.HistoryReset variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@backup);
            case AccountEvent.SessionExpired variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeAccountEvent.AllocationSize()", value));
        }
    }

    public override void Write(AccountEvent value, BigEndianStream stream) {
        switch (value) {
            case AccountEvent.ListAdvanced variant_value:
                stream.WriteInt(1);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@seq, stream);
                break;
            case AccountEvent.SelfRemoved variant_value:
                stream.WriteInt(2);
                break;
            case AccountEvent.TrustReset variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@resetId, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.@devices, stream);
                FfiConverterSequenceString.INSTANCE.Write(variant_value.@deviceNames, stream);
                break;
            case AccountEvent.HistoryReset variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@backup, stream);
                break;
            case AccountEvent.SessionExpired variant_value:
                stream.WriteInt(5);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeAccountEvent.Write()", value));
        }
    }
}







