public class FsyncException: UniffiException {
    FsyncException() : base() {}
    FsyncException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    
    public class NotPaired : FsyncException {
        public NotPaired() : base() {}
    }
    
    
    
    public class PeerOffline : FsyncException {
        public PeerOffline() : base() {}
    }
    
    
    
    public class Network : FsyncException {
        // Members
        public string @msg;

        // Constructor
        public Network(
                string @msg) : base(
                "@msg" + "=" + @msg) {

            this.@msg = @msg;
        }
    }
    
    
    public class Integrity : FsyncException {
        public Integrity() : base() {}
    }
    
    
    
    public class TooLarge : FsyncException {
        public TooLarge() : base() {}
    }
    
    
    
    public class Auth : FsyncException {
